// ─── Main Component ───────────────────────────────────────────────────────────

export default function RSVPForm() {
  // Read ?to= from URL
  const defaultNama = useRef('');

  // Form state
  const [form, setForm] = useState<FormData>({
    nama            : '',
    status_kehadiran: '',
    jumlah_tamu     : 1,
    ucapan          : '',
  });

  const [submitState,      setSubmitState]      = useState<SubmitState>('idle');
  const [errorMsg,         setErrorMsg]         = useState('');
  const [focused,          setFocused]          = useState<string | null>(null);
  const [showSuccessToast, setShowSuccessToast] = useState(false);

  // ── Wishes Feed State ───────────────────────────────────────────────────────
  const [wishes,   setWishes]   = useState<Wish[]>(INITIAL_WISHES);
  const [isClient, setIsClient] = useState(false);

  // Initialize and load saved wishes + Supabase fetch + Realtime subscription
  useEffect(() => {
    setIsClient(true);
    const params = new URLSearchParams(window.location.search);
    const to = params.get('to') ?? params.get('guest') ?? '';
    if (to) {
      defaultNama.current = decodeURIComponent(to);
      setForm(prev => ({ ...prev, nama: decodeURIComponent(to) }));
    }

    // Load locally persisted wishes if available
    try {
      const saved = localStorage.getItem('ar_wedding_guestbook');
      if (saved) {
        const parsed: Wish[] = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          setWishes(parsed);
        }
      }
    } catch {
      // Ignore localStorage errors
    }

    // Fetch live wishes specifically from 'wedding_guestbook'
    const fetchSupabaseWishes = async () => {
      try {
        const { data, error } = await supabase
          .from('wedding_guestbook')
          .select('id, guest_name, message, created_at')
          .order('created_at', { ascending: false });

        if (!error && data && data.length > 0) {
          setWishes((prev) => {
            const combined: Wish[] = [...data];
            prev.forEach(p => {
              if (!combined.some(c => c.id === p.id || (c.guest_name === p.guest_name && c.message === p.message))) {
                combined.push(p);
              }
            });
            combined.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
            return combined;
          });
        }
      } catch (e) {
        console.warn('[RSVPForm] wedding_guestbook fetch fallback to local list:', e);
      }
    };

    fetchSupabaseWishes();

    // Supabase Real-time Channel Listener for 'wedding_guestbook'
    const channel = supabase
      .channel('wedding_guestbook_live')
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'wedding_guestbook' },
        (payload) => {
          const newRecord = payload.new as Wish;
          if (newRecord && newRecord.guest_name) {
            setWishes((prev) => {
              // Deduplicate if already added optimistically
              if (prev.some(w => w.id === newRecord.id || (w.guest_name === newRecord.guest_name && w.message === newRecord.message))) {
                return prev.map(w =>
                  (w.guest_name === newRecord.guest_name && w.message === newRecord.message) ? newRecord : w
                );
              }
              const updated = [newRecord, ...prev];
              try {
                localStorage.setItem('ar_wedding_guestbook', JSON.stringify(updated.slice(0, 50)));
              } catch {}
              return updated;
            });
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  // Field helpers
  const set = (field: keyof FormData) =>
    (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>
      setForm(prev => ({ ...prev, [field]: e.target.value }));

  const focusStyle = (name: string): React.CSSProperties => ({
    ...inputBase,
    borderColor: focused === name ? 'rgba(245,158,11,0.65)' : 'rgba(245,158,11,0.2)',
    boxShadow  : focused === name ? '0 0 0 3px rgba(180,83,9,0.18)' : 'none',
  });

  // ── Handle Submit ───────────────────────────────────────────────────────────
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!form.nama.trim()) {
      setErrorMsg('Nama lengkap tidak boleh kosong.');
      return;
    }
    if (!form.status_kehadiran) {
      setErrorMsg('Silakan pilih konfirmasi kehadiran Anda.');
      return;
    }
    setErrorMsg('');
    setSubmitState('loading');

    const tempId = `guestbook-${Date.now()}`;
    const payload = {
      guest_name: form.nama.trim(),
      message   : form.ucapan.trim() || 'Selamat berbahagia untuk Adli & Rima!',
      created_at: new Date().toISOString(),
    };

    const newWish: Wish = {
      id: tempId,
      ...payload,
    };

    // 1. DYNAMIC IMMEDIATE APPEND: Prepend immediately to live state without page reload
    setWishes((prev) => {
      const nextList = [newWish, ...prev.filter(w => w.id !== tempId)];
      try {
        localStorage.setItem('ar_wedding_guestbook', JSON.stringify(nextList.slice(0, 50)));
      } catch {}
      return nextList;
    });

    // 2. Clear ucapan, trigger success toast without page reload
    setForm(prev => ({ ...prev, ucapan: '' }));
    setSubmitState('success');
    setShowSuccessToast(true);

    setTimeout(() => {
      setSubmitState('idle');
    }, 1500);

    setTimeout(() => {
      setShowSuccessToast(false);
    }, 4500);

    // 3. Supabase insert specifically to 'wedding_guestbook'
    try {
      const { data, error } = await supabase
        .from('wedding_guestbook')
        .insert([payload])
        .select();

      if (!error && data && data[0]) {
        // Swap tempId with confirmed Supabase record
        setWishes(prev => prev.map(w => (w.id === tempId ? data[0] : w)));
      } else if (error) {
        console.warn('[RSVPForm] wedding_guestbook insert warning (persisted locally in UI feed):', error);
      }
    } catch (err) {
      console.warn('[RSVPForm] wedding_guestbook insert note:', err);
    }
  };

  // Attendance card button
  const AttendanceCard = ({
    value, label, icon,
  }: {
    value: 'hadir' | 'tidak_hadir';
    label: string;
    icon : React.ReactNode;
  }) => {
    const selected = form.status_kehadiran === value;
    return (
      <motion.button
        type="button"
        onClick={() => setForm(prev => ({ ...prev, status_kehadiran: value }))}
        className="flex-1 flex flex-col items-center gap-2 py-4 px-3 rounded-xl transition-all duration-200 relative overflow-hidden cursor-pointer"
        style={{
          background: selected ? 'rgba(120,53,15,0.35)' : 'rgba(15,23,42,0.5)',
          border: selected ? '1px solid rgba(245,158,11,0.6)' : '1px solid rgba(245,158,11,0.18)',
          backdropFilter: 'blur(8px)',
        }}
        whileTap={{ scale: 0.97 }}
        whileHover={!selected ? { backgroundColor: 'rgba(15,23,42,0.65)' } : {}}
        aria-pressed={selected}
      >
        <div
          className="relative w-10 h-10 rounded-full flex items-center justify-center"
          style={{
            background: selected ? 'rgba(180,83,9,0.35)' : 'rgba(15,23,42,0.6)',
            border    : selected ? '1px solid rgba(245,158,11,0.5)' : '1px solid rgba(245,158,11,0.18)',
          }}
        >
          {icon}
        </div>

        <span
          className="text-xs tracking-[0.2em] uppercase font-medium"
          style={{
            fontFamily: FONT_SANS,
            color: selected ? 'rgba(245,158,11,0.95)' : 'rgba(148,163,184,0.7)',
          }}
        >
          {label}
        </span>

        {selected && (
          <motion.div
            className="absolute top-2 right-2 w-4 h-4 rounded-full flex items-center justify-center"
            style={{ background: 'rgba(245,158,11,0.9)' }}
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ type: 'spring', stiffness: 300, damping: 20 }}
          >
            <svg className="w-2.5 h-2.5 text-slate-900" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
            </svg>
          </motion.div>
        )}
      </motion.button>
    );
  };

  return (
    <section className="w-full py-16 px-4 flex flex-col items-center gap-10 relative overflow-hidden">
      {/* Background radial glow */}
      <div
        className="absolute inset-0 pointer-events-none"
        aria-hidden
        style={{
          background: 'radial-gradient(ellipse 70% 50% at 50% 50%, rgba(120,53,15,0.08) 0%, transparent 70%)',
        }}
      />

      <SectionHeader />

      {/* ── 1. RSVP FORM CARD ── */}
      <motion.div
        className="w-full max-w-lg rounded-2xl relative overflow-hidden shadow-2xl"
        style={GLASS}
        initial={{ opacity: 0, y: 25 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true }}
        transition={{ duration: 0.6, ease: 'easeOut' }}
      >
        <div
          className="h-px w-full"
          style={{ background: 'linear-gradient(90deg, transparent, rgba(245,158,11,0.5), transparent)' }}
        />

        <div className="p-6 sm:p-8">
          {/* Success Toast Banner */}
          <AnimatePresence>
            {showSuccessToast && (
              <motion.div
                className="mb-6 p-4 rounded-xl border flex items-center gap-3 shadow-lg"
                style={{
                  background: 'rgba(16, 185, 129, 0.15)',
                  borderColor: 'rgba(52, 211, 153, 0.45)',
                  backdropFilter: 'blur(8px)',
                }}
                initial={{ opacity: 0, y: -10, scale: 0.95 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, y: -10, scale: 0.95 }}
                transition={{ duration: 0.3 }}
              >
                <div className="w-7 h-7 rounded-full bg-emerald-500/20 border border-emerald-400 flex items-center justify-center shrink-0">
                  <svg className="w-4 h-4 text-emerald-300" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                  </svg>
                </div>
                <div className="flex-1 text-left">
                  <p className="text-xs font-semibold text-emerald-200" style={{ fontFamily: FONT_SANS }}>
                    Konfirmasi &amp; Ucapan Terkirim!
                  </p>
                  <p className="text-[11px] text-emerald-300/80" style={{ fontFamily: FONT_SERIF }}>
                    Doa restu Anda telah langsung terbit di feed pesan di bawah.
                  </p>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <form onSubmit={handleSubmit} className="flex flex-col gap-5">
            {/* Nama Lengkap */}
            <div>
              <Label>Nama Lengkap</Label>
              <input
                type="text"
                value={form.nama}
                onChange={set('nama')}
                onFocus={() => setFocused('nama')}
                onBlur={() => setFocused(null)}
                placeholder="Masukkan nama Anda"
                className="w-full px-4 py-3 rounded-xl placeholder-slate-500 text-sm"
                style={focusStyle('nama')}
                autoComplete="name"
                required
              />
            </div>

            {/* Attendance Selection */}
            <div>
              <Label>Konfirmasi Kehadiran</Label>
              <div className="flex gap-3">
                <AttendanceCard
                  value="hadir"
                  label="Hadir"
                  icon={
                    <svg className="w-5 h-5 text-amber-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  }
                />
                <AttendanceCard
                  value="tidak_hadir"
                  label="Tidak Hadir"
                  icon={
                    <svg className="w-5 h-5 text-amber-500/70" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M9.75 9.75l4.5 4.5m0-4.5l-4.5 4.5M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  }
                />
              </div>
            </div>

            {/* Jumlah Tamu (Conditional when Hadir) */}
            <AnimatePresence>
              {form.status_kehadiran === 'hadir' && (
                <motion.div
                  key="jumlah"
                  initial={{ opacity: 0, height: 0, y: -8 }}
                  animate={{ opacity: 1, height: 'auto', y: 0 }}
                  exit={{ opacity: 0, height: 0, y: -8 }}
                  transition={{ duration: 0.35, ease: [0.4, 0, 0.2, 1] }}
                  style={{ overflow: 'hidden' }}
                >
                  <Label>Jumlah Tamu</Label>
                  <div className="flex items-center gap-3">
                    <motion.button
                      type="button"
                      onClick={() => setForm(p => ({ ...p, jumlah_tamu: Math.max(1, p.jumlah_tamu - 1) }))}
                      className="w-10 h-10 rounded-xl flex items-center justify-center text-amber-400 text-xl shrink-0 cursor-pointer"
                      style={GLASS_INNER}
                      whileTap={{ scale: 0.9 }}
                      aria-label="Kurangi"
                    >
                      −
                    </motion.button>

                    <div
                      className="flex-1 h-10 rounded-xl flex items-center justify-center"
                      style={{ ...GLASS_INNER, border: '1px solid rgba(245,158,11,0.25)' }}
                    >
                      <span className="text-amber-300 text-lg tabular-nums" style={{ fontFamily: FONT_DISPLAY }}>
                        {form.jumlah_tamu} Tamu
                      </span>
                    </div>

                    <motion.button
                      type="button"
                      onClick={() => setForm(p => ({ ...p, jumlah_tamu: Math.min(10, p.jumlah_tamu + 1) }))}
                      className="w-10 h-10 rounded-xl flex items-center justify-center text-amber-400 text-xl shrink-0 cursor-pointer"
                      style={GLASS_INNER}
                      whileTap={{ scale: 0.9 }}
                      aria-label="Tambah"
                    >
                      +
                    </motion.button>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>

            {/* Digital Envelope (Conditional when Tidak Hadir) */}
            <AnimatePresence>
              {form.status_kehadiran === 'tidak_hadir' && (
                <DigitalEnvelope key="envelope" />
              )}
            </AnimatePresence>

            {/* Ucapan & Doa */}
            <div>
              <Label>Ucapan &amp; Doa Restu</Label>
              <textarea
                value={form.ucapan}
                onChange={set('ucapan')}
                onFocus={() => setFocused('ucapan')}
                onBlur={() => setFocused(null)}
                placeholder="Tuliskan ucapan dan doa terbaik Anda untuk kedua mempelai…"
                rows={3}
                className="w-full px-4 py-3 rounded-xl placeholder-slate-500 resize-none leading-relaxed text-sm"
                style={focusStyle('ucapan')}
                required
              />
            </div>

            {/* Error Message Banner */}
            <AnimatePresence>
              {errorMsg && (
                <motion.div
                  className="flex items-start gap-3 px-4 py-3 rounded-xl"
                  style={{ background: 'rgba(239,68,68,0.1)', border: '1px solid rgba(239,68,68,0.25)' }}
                  initial={{ opacity: 0, y: -6 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0 }}
                >
                  <p className="text-xs text-red-400 leading-relaxed" style={{ fontFamily: FONT_SANS }}>
                    {errorMsg}
                  </p>
                </motion.div>
              )}
            </AnimatePresence>

            {/* Submit Button */}
            <motion.button
              type="submit"
              disabled={submitState === 'loading'}
              className="relative w-full py-3.5 rounded-xl text-xs sm:text-sm tracking-[0.25em] uppercase font-semibold overflow-hidden shadow-lg cursor-pointer transition-all duration-300"
              style={{
                fontFamily: FONT_SANS,
                background: 'linear-gradient(135deg, rgba(180, 83, 9, 0.85) 0%, rgba(120, 53, 15, 0.95) 100%)',
                border    : '1px solid rgba(245, 158, 11, 0.55)',
                color     : '#fef3c7',
                boxShadow : '0 4px 20px rgba(217, 119, 6, 0.3)',
              }}
              whileHover={{ scale: 1.02, boxShadow: '0 6px 25px rgba(245, 158, 11, 0.45)' }}
              whileTap={{ scale: 0.98 }}
            >
              <span className="relative flex items-center justify-center gap-2">
                {submitState === 'loading' ? (
                  <>
                    <svg className="w-4 h-4 animate-spin text-amber-200" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2}>
                      <circle cx="12" cy="12" r="10" strokeOpacity=".2" />
                      <path d="M12 2a10 10 0 0110 10" strokeLinecap="round" />
                    </svg>
                    Mengirimkan…
                  </>
                ) : (
                  <>
                    <svg className="w-4 h-4 text-amber-300" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M6 12L3.269 3.126A59.768 59.768 0 0121.485 12 7.5 7.5 0 0112 17.25h-2.625c-.621 0-1.125.504-1.125 1.125v3.375" />
                    </svg>
                    Kirim Ucapan &amp; Konfirmasi
                  </>
                )}
              </span>
            </motion.button>
          </form>
        </div>

        <div
          className="h-px w-full"
          style={{ background: 'linear-gradient(90deg, transparent, rgba(245,158,11,0.3), transparent)' }}
        />
      </motion.div>

      {/* ── 2. REAL-TIME WISHES & GREETINGS FEED (wedding_guestbook) ── */}
      <div className="w-full max-w-lg flex flex-col gap-4">
        {/* Feed Header */}
        <div className="flex items-center justify-between px-2 pt-2">
          <div className="flex items-center gap-2">
            <span className="text-amber-400 text-base">💌</span>
            <h3
              className="text-base sm:text-lg text-amber-300 font-medium tracking-wide drop-shadow-[0_1px_2px_rgba(0,0,0,0.9)]"
              style={{ fontFamily: FONT_DISPLAY }}
            >
              Buku Tamu &amp; Doa Restu
            </h3>
          </div>
          <span
            className="px-2.5 py-0.5 rounded-full text-xs font-semibold bg-amber-500/20 text-amber-300 border border-amber-500/35"
            style={{ fontFamily: FONT_SANS }}
          >
            {wishes.length} Pesan
          </span>
        </div>

        {/* Scrollable Message List */}
        <div className="max-h-[520px] overflow-y-auto space-y-3.5 pr-1" style={{ scrollbarWidth: 'thin' }}>
          <AnimatePresence initial={false}>
            {wishes.map((item) => {
              const initialLetter = item.guest_name ? item.guest_name.trim().charAt(0).toUpperCase() : 'T';

              return (
                <motion.div
                  key={item.id}
                  className="p-4 sm:p-5 rounded-2xl border backdrop-blur-md shadow-lg flex flex-col gap-2.5 transition-all"
                  style={{
                    background: 'rgba(15, 23, 42, 0.72)',
                    borderColor: 'rgba(245, 158, 11, 0.2)',
                  }}
                  initial={{ opacity: 0, y: -15, scale: 0.97 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.95 }}
                  transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
                >
                  {/* Card Header (Avatar + Name + Timestamp) */}
                  <div className="flex items-center justify-between gap-2">
                    <div className="flex items-center gap-3 min-w-0">
                      {/* Avatar initial */}
                      <div className="w-8 h-8 rounded-full bg-gradient-to-br from-amber-400/30 to-amber-600/40 border border-amber-400/40 flex items-center justify-center shrink-0">
                        <span className="text-amber-200 font-bold text-xs" style={{ fontFamily: FONT_DISPLAY }}>
                          {initialLetter}
                        </span>
                      </div>

                      <div className="flex flex-col min-w-0">
                        <p className="text-sm text-amber-200 font-semibold truncate" style={{ fontFamily: FONT_DISPLAY }}>
                          {item.guest_name}
                        </p>
                        <p className="text-[10px] text-slate-400" style={{ fontFamily: FONT_SERIF }}>
                          {isClient ? formatRelativeTime(item.created_at) : 'Baru saja'}
                        </p>
                      </div>
                    </div>
                  </div>

                  {/* Message Body */}
                  <p
                    className="text-xs sm:text-sm text-slate-200/90 leading-relaxed italic pl-1 border-l-2 border-amber-500/30 ml-2"
                    style={{ fontFamily: FONT_SERIF }}
                  >
                    &ldquo;{item.message}&rdquo;
                  </p>
                </motion.div>
              );
            })}
          </AnimatePresence>
        </div>
      </div>
    </section>
  );
}
